  'No se pudo descargar el cliente oficial. Comprueba la conexión a Internet e inténtalo de nuevo.': 'Não foi possível baixar o cliente oficial. Verifique sua conexão com a Internet e tente novamente.',
  'La descarga no superó la comprobación de seguridad y no se ha ejecutado.': 'O download falhou na verificação de segurança e não foi executado.',
