    'Encadeia temas, ideias, resumo, indexação (ideias e trechos) e descoberta de relações para toda a biblioteca filtrada.',
  'Procesar todo encadena para las {n} obra(s) filtrada(s): temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones. Es una operación larga que consume tokens del modelo seleccionado. ¿Continuar?':
    'Processar tudo encadeia para as {n} obra(s) filtrada(s): temas, ideias, resumo, indexação (ideias e trechos) e descoberta de relações. É uma operação longa que consome tokens do modelo selecionado. Continuar?',
