  'Buscar y fusionar duplicados': 'Buscar e mesclar duplicados',
  'Detecta obras repetidas (mismo DOI, o mismo título, año y autores) y te deja revisarlas y fusionarlas conservando una sola copia. La misma obra en varias colecciones de Zotero no se duplica.':
    'Detecta obras repetidas (mesmo DOI, ou mesmo título, ano e autores) e permite que você as revise e mescle, mantendo uma única cópia. A mesma obra em várias coleções do Zotero não é duplicada.',
