  'Fusionar todos los duplicados': 'Mesclar todos os duplicados',
  'Se fusionarán {g} grupo(s), conservando en cada uno la copia marcada y reasignando sus ideas, evidencia y etiquetas. Las {n} copias sobrantes se eliminarán de la biblioteca de Nodus (Zotero no se modifica). ¿Continuar?':
    'Serão mesclados {g} grupo(s), mantendo em cada um a cópia marcada e reatribuindo suas ideias, evidências e etiquetas. As {n} cópias excedentes serão removidas da biblioteca do Nodus (o Zotero não é modificado). Continuar?',
  'Duplicados': 'Duplicados',
