  'Fusionar todas las ideas duplicadas': 'Mesclar todas as ideias duplicadas',
  'Se hará primero una copia de seguridad completa de la base de datos. Después se fusionarán {g} grupo(s), conservando en cada uno la idea marcada y reasignándole toda la evidencia, ocurrencias, temas y conexiones del grafo de las {n} copias sobrantes, que se eliminarán. La evidencia no se pierde. ¿Continuar?':
    'Primeiro será feito um backup completo do banco de dados. Depois serão mesclados {g} grupo(s), mantendo em cada um a ideia marcada e reatribuindo a ela toda a evidência, ocorrências, temas e conexões do grafo das {n} cópias excedentes, que serão removidas. Nenhuma evidência é perdida. Continuar?',
