  'Incompleto': 'Incompleta',
  'Búsqueda semántica': 'Busca semântica',
  'Texto citable': 'Texto citável',
  'Pulsa «Analizar» en la fila de una obra, o selecciona varias y analízalas juntas. Nodus lee el texto, extrae temas padre, ideas con evidencia y relaciones, y las añade al grafo. La columna Estado te dice en qué punto va cada obra.': 'Clique em «Analisar» na linha de uma obra, ou selecione várias e analise-as juntas. O Nodus lê o texto, extrai temas principais, ideias com evidência e relações, e as adiciona ao grafo. A coluna Estado mostra em que ponto está cada obra.',
