  'Lectura:': 'Leitura:',
  'Preguntar al asistente sobre esta obra': 'Perguntar ao assistente sobre esta obra',
  'Analiza esta lectura dentro del corpus: ideas extraídas, temas, huecos, contradicciones y próximas lecturas relacionadas.':
    'Analise esta leitura dentro do corpus: ideias extraídas, temas, lacunas, contradições e próximas leituras relacionadas.',
