  'Mostrar hasta 250 ideas del tema': 'Mostrar até 250 ideias do tema',
  'Mostrar todas las ideas del tema': 'Mostrar todas as ideias do tema',
  'Hasta 250': 'Até 250',
  'Mostrar todas las ideas del tema (puede ir más lento)': 'Mostrar todas as ideias do tema (pode ficar mais lento)',
  'Conectada con': 'Conectada com',
