  'Demo de bases de datos': 'Demo de bancos de dados',
  'Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.':
    'Três tabelas de pesquisa com todos os tipos de coluna, relações, registros, análises, uma conversa e notas de exemplo. Inclui um tutorial guiado.',
  'Cargar demo de bases de datos': 'Carregar demo de bancos de dados',
  'Cargar datos de ejemplo': 'Carregar dados de exemplo',
  'Tutorial de bases de datos': 'Tutorial de bancos de dados',
  'La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.':
    'A lista de bancos de dados, a tabela com colunas tipadas, a edição de células e as seções de análise e chat.',
  'Se mostrará el tutorial de bases de datos.': 'O tutorial de bancos de dados será exibido.',
  'Bienvenido al modo bases de datos': 'Bem-vindo ao modo bancos de dados',
  'Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.':
    'Este é o modo bancos de dados do Nodus: um gerenciador de tabelas ao estilo Notion, integrado ao seu app. Vou te mostrar em um minuto as peças dele com três bancos de dados de exemplo já carregados. Você pode sair quando quiser e rever o tutorial em Configurações.',
  'Tus bases de datos': 'Seus bancos de dados',
  'En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.':
    'Na barra lateral aparecem todos os seus bancos de dados. Cada um tem um identificador único gerado automaticamente. Clique em um para abri-lo, ou no botão + para criar um novo. Aqui embaixo também estão as seções de Análise e Chat.',
  'La tabla': 'A tabela',
  'Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.':
    'Cada banco de dados é uma tabela de colunas tipadas: título, texto, número, data, hora, seleção, seleção múltipla e caixa de seleção. No topo você verá o número total de entradas e a porcentagem que representam do total de todos os seus bancos de dados.',
  'Edita directamente': 'Edite diretamente',
  'Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.':
    'Clique em qualquer célula para editá-la instantaneamente. As colunas de seleção mostram opções coloridas que você pode adicionar na hora; as caixas de seleção são marcadas com um clique. Passe o mouse sobre uma linha para excluí-la.',
  'Columnas a tu medida': 'Colunas sob medida',
  'Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.':
    'Clique no cabeçalho de uma coluna para renomeá-la, mudar seu tipo ou gerenciar suas opções, e use o botão + no final do cabeçalho para adicionar novas colunas. Com “Nova linha” você adiciona registros.',
  'Análisis (próximamente)': 'Análise (em breve)',
  'Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.':
    'Aqui você poderá escolher um banco de dados e obter estatísticas automáticas mais um relatório com IA, com gráficos e o cálculo à vista para que seja reproduzível. Chega em uma próxima fase.',
  'Chat de datos (próximamente)': 'Chat de dados (em breve)',
  'Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.':
    'Um chat adaptado para conversar com um ou vários dos seus bancos de dados, capaz de gerar gráficos e consultas reproduzíveis. Também chega em uma próxima fase.',
  'Listo para tus datos': 'Pronto para seus dados',
  'Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.':
    'Esta é uma demonstração com dados de exemplo. Quando quiser começar com os seus, crie um banco de dados na barra lateral e adicione suas colunas. Em breve você também poderá importar CSV e enviar arquivos em massa.',
