  "Se eliminarán «{name}», sus {n} elementos internos y todas sus calificaciones. Esta acción no se puede deshacer.": "«{name}», seus {n} itens internos e todas as suas notas serão excluídos. Esta ação não pode ser desfeita.",
  "Se eliminará «{name}» y todas sus calificaciones. Esta acción no se puede deshacer.": "«{name}» e todas as suas notas serão excluídos. Esta ação não pode ser desfeita.",
