  'Chat de Nodus dentro de Zotero: pregunta sobre el ítem abierto con el contexto de tu biblioteca (resumen, ideas, conexiones). Instala el plugin en Zotero; se conecta a Nodus automáticamente.': 'Converse com o Nodus dentro do Zotero: pergunte sobre o item aberto com a sua biblioteca como contexto (resumo, ideias, conexões). Instale o plugin no Zotero; ele se conecta ao Nodus automaticamente.',
