  'Diseña unidades para el docente o apuntes para entregar al alumnado, siempre desde tus fuentes.': 'Planeje unidades para o docente ou materiais para entregar aos estudantes, sempre com base nas suas fontes.',
  'Elige si necesitas una planificación para impartir la lección o apuntes listos para entregar.': 'Escolha entre um planejamento para ministrar a aula e materiais prontos para entregar.',
  'Elige si necesitas apuntes para aprender o una planificación para enseñar el tema.': 'Escolha entre materiais para aprender e um planejamento para ensinar o tema.',
  'Escribe el tema o la lección que quieres preparar. El informe diseñará objetivos, secuencia, actividades y evaluación usando tus materiales.': 'Informe o tema ou a aula que deseja preparar. O relatório criará objetivos, sequência, atividades e avaliação com base nos seus materiais.',
  'Escribe el tema de los apuntes. El informe lo explicará paso a paso con ejemplos y autoevaluación usando tus materiales.': 'Informe o tema do material. O relatório irá explicá-lo passo a passo, com exemplos e autoavaliação, com base nos seus materiais.',
