  'Generará objetivos, secuencia, actividades, comprobaciones de comprensión y evaluación para el docente.': 'Irá gerar objetivos, sequência, atividades, verificações de compreensão e avaliação para o docente.',
  'Generará explicaciones, definiciones, ejemplos, síntesis y autoevaluación dirigidos al alumnado.': 'Irá gerar explicações, definições, exemplos, sínteses e autoavaliação voltados aos estudantes.',
  'En «Crear», Unidades didácticas ya permite generar una planificación para el docente o apuntes para el alumnado a partir de tus materiales. Las demás secciones punteadas siguen abiertas a tus sugerencias. Puedes repetir este tutorial desde Ajustes.': 'Em “Criar”, as Unidades didáticas agora permitem gerar um planejamento para o docente ou materiais para os estudantes a partir das suas fontes. As demais seções pontilhadas continuam abertas às suas sugestões. Você pode repetir este tutorial nas Configurações.',
