  "Limpieza automática de copias antiguas": "Limpeza automática de backups antigos",
  "Usa el mismo día y hora que las copias automáticas. Si Nodus estaba cerrado, la limpieza pendiente se ejecuta al volver a abrirlo.": "Usa o mesmo dia e horário dos backups automáticos. Se o Nodus estava fechado, a limpeza pendente é executada quando ele for aberto novamente.",
  "Configura primero la carpeta de Recuperación y la contraseña maestra para poder verificar una copia superviviente.": "Configure primeiro a pasta de Recuperação e a senha mestra para poder verificar um backup preservado.",
