  "años": "anos",
  "{count} copia(s), {size}, supera(n) ahora la antigüedad configurada.": "{count} backup(s), {size}, excede(m) atualmente a idade configurada.",
  "Siempre se conservan al menos las tres copias normales más recientes. Las copias de otros equipos y los snapshots pre-update nunca entran en esta limpieza.": "Pelo menos os três backups normais mais recentes são sempre preservados. Backups de outros computadores e snapshots pré-atualização nunca entram nesta limpeza.",
  "{count} copia(s) permanece(n) en la papelera de seguridad.": "{count} backup(s) permanece(m) na lixeira de segurança.",
  "{count} copia(s) ({size}) ya cumplió/cumplieron siete días en la papelera de seguridad y se eliminará(n) definitivamente en esta limpieza.": "{count} backup(s) ({size}) já completou/completaram sete dias na lixeira de segurança e será/serão excluído(s) definitivamente nesta limpeza.",
  "Las copias seleccionadas se mueven primero a una papelera privada dentro de la carpeta de Recuperación. Solo se eliminan definitivamente después de siete días y tras verificar otra copia válida.": "Os backups selecionados são primeiro movidos para uma lixeira privada dentro da pasta de Recuperação. Eles só são excluídos definitivamente depois de sete dias e após a verificação de outro backup válido.",
  "Al activar esta opción, el límite de antigüedad sustituye la rotación compacta anterior para las nuevas copias de este equipo.": "Ao ativar esta opção, o limite de idade substitui a rotação compacta anterior para novos backups deste computador.",
  "Para cambiar la antigüedad, desactiva primero la limpieza y vuelve a activarla para confirmar el nuevo alcance.": "Para alterar a idade, primeiro desative a limpeza e ative-a novamente para confirmar o novo alcance.",
  "Limpiando…": "Limpando…",
  "Revisar y limpiar ahora": "Revisar e limpar agora",
  "Última limpieza": "Última limpeza",
  "¿Activar la limpieza automática?": "Ativar a limpeza automática?",
  "Esta opción puede retirar copias antiguas automáticamente. Comprueba con atención la antigüedad seleccionada antes de continuar.": "Esta opção pode retirar backups antigos automaticamente. Confira com atenção a idade selecionada antes de continuar.",
  "Con la configuración actual, {count} copia(s) ({size}) pasaría(n) a la papelera de seguridad.": "Com a configuração atual, {count} backup(s) ({size}) seria(m) movido(s) para a lixeira de segurança.",
  "Las tres copias normales más recientes, las copias de otros equipos y los snapshots pre-update quedan protegidos.": "Os três backups normais mais recentes, os backups de outros computadores e os snapshots pré-atualização ficam protegidos.",
  "Ninguna copia que se mueva en esta ejecución se eliminará definitivamente: permanecerá siete días en la papelera de seguridad.": "Nenhum backup movido nesta execução será excluído definitivamente: permanecerá sete dias na lixeira de segurança.",
  "Activar y ejecutar limpieza": "Ativar e executar limpeza",
  "¿Revisar y limpiar copias antiguas?": "Revisar e limpar backups antigos?",
  "{count} copia(s) ({size}) cumple(n) ahora la regla de antigüedad.": "{count} backup(s) ({size}) atende(m) atualmente à regra de idade.",
  "Nodus volverá a calcular y verificar todo justo antes de mover archivos. Si algo no coincide, la operación se cancela sin borrar datos.": "O Nodus vai recalcular e verificar tudo imediatamente antes de mover os arquivos. Se algo não corresponder, a operação será cancelada sem excluir dados.",
  "Las copias pasarán primero a la papelera de seguridad durante siete días.": "Os backups irão primeiro para a lixeira de segurança durante sete dias.",
  "Ejecutar limpieza segura": "Executar limpeza segura",
  "{count} copia(s) se movió/movieron a la papelera de seguridad.": "{count} backup(s) foi/foram movido(s) para a lixeira de segurança.",
  "{count} copia(s) se eliminó/eliminaron definitivamente tras siete días.": "{count} backup(s) foi/foram excluído(s) definitivamente após sete dias.",
  "No hay copias que superen la antigüedad configurada.": "Não há backups que excedam a idade configurada.",
  "La vista previa ya no está disponible. Revísala de nuevo antes de limpiar.": "A visualização não está mais disponível. Revise-a novamente antes de limpar.",
  "La carpeta de copias cambió desde la vista previa. No se ha modificado nada; revisa el alcance y vuelve a confirmar.": "A pasta de backups mudou desde a visualização. Nada foi alterado; revise o alcance e confirme novamente.",
  "La confirmación de limpieza no es válida. Revisa de nuevo el alcance.": "A confirmação da limpeza não é válida. Revise o alcance novamente.",
  "Nodus Connector para Chrome": "Nodus Connector para Chrome",
  "Guarda la página o documento abierto en la Biblioteca de Nodus con metadatos, archivos, colección y etiquetas. Solo lee la pestaña cuando pulsas el icono.": "Salva a página ou o documento aberto na Biblioteca Nodus com metadados, arquivos, coleção e etiquetas. A guia só é lida quando você clica no ícone.",
  "Activar Nodus Connector para Chrome": "Ativar o Nodus Connector para Chrome",
