  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en {host} dentro de Nodus, porque las cookies no se comparten entre navegadores.": "Atenção: se você entrar no seu navegador, a sessão fica lá. Você continuará sem login em {host} dentro do Nodus, porque os cookies não são compartilhados entre navegadores.",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en Google dentro de Nodus, porque las cookies no se comparten entre navegadores.": "Atenção: se você entrar no seu navegador, a sessão fica lá. Você continuará sem login no Google dentro do Nodus, porque os cookies não são compartilhados entre navegadores.",
  "Si {host} admite entrar con contraseña o con un enlace por correo, esa vía sí funciona aquí dentro, y Nodus recordará la sesión.": "Se {host} aceitar senha ou um link por e-mail, esse caminho funciona aqui dentro, e o Nodus vai lembrar da sessão.",
  "Volver e intentar con contraseña": "Voltar e tentar com senha",
  "Usar {host} en mi navegador": "Usar {host} no meu navegador",
  "Para que Nodus lea tu Gmail o tu Drive haría falta otra cosa: conectar la cuenta desde Ajustes, que es la vía que Google sí admite para aplicaciones de escritorio. Todavía no está disponible.": "Para o Nodus ler seu Gmail ou Drive seria preciso outra coisa: conectar a conta nas Configurações, o caminho que o Google permite para aplicativos de desktop. Ainda não disponível.",
  "No es un fallo de Nodus: Google rechaza el inicio de sesión desde cualquier navegador incrustado en otra aplicación.": "Não é um problema do Nodus: o Google recusa o login a partir de qualquer navegador incorporado em outro aplicativo.",
  "Google no permite iniciar sesión desde un navegador integrado": "O Google não permite fazer login em um navegador integrado",
